/**
 * Resources relevant to a set of dimensions, best match first (most dimensions covered, then catalogue order).
 * Returns an empty array when nothing matches.
 */
export function resourcesFor(dimensions: DimensionId[]): Resource[] {
  const wanted = new Set(dimensions);
  const scored = RESOURCES.map((r, order) => ({
    r,
    order,
    score: r.dimensions.filter((d) => wanted.has(d)).length,
  })).filter((x) => x.score > 0);
  scored.sort((a, b) => b.score - a.score || a.order - b.order);
  return scored.map((x) => x.r);
}
